mapper.select:
SELECT
    SCHEDULE_SEQ, BROD_CODE, CENTER_ID, BROD_DAY
FROM TB_BRODCENTERSCH
WHERE CREATE_CHECK = 'N'
  AND CENTER_ID = #{centerId}
  AND BROD_DAY = #{brodDay}

SELECT * FROM ( SELECT TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY B.SCHEDULE_SEQ DESC) AS RNUM, A.BROD_NAME, C.CENTER_NM, B.BROD_DAY AS brodDay, B.CENTER_ID, B.BROD_CODE AS brodCode, B.SCHEDULE_SEQ, CASE B.BROD_DAY WHEN '20991231' THEN CONCAT(C.CENTER_STARTTIME, '/', C.CENTER_ENDTIME) ELSE ( SELECT CONCAT(D.START_TIME, '/', D.END_TIME) FROM TB_CENTERANNIVERSARY D WHERE D.CENTER_ID = B.CENTER_ID AND B.BROD_DAY BETWEEN D.CENTER_ANNISTARTDAY AND D.CENTER_ANNIENDDAY LIMIT 1 ) END AS CENTER_STARTTIME, B.CREATE_CHECK, CASE B.CREATE_CHECK WHEN 'N' THEN '00000000' ELSE TO_CHAR(B.CREATE_REGDATE, 'YYYYMMDD') END AS CREATE_REGDATE, B.DID_DOWNCHECK AS didDownCheck, TO_CHAR(B.DID_DOWNLOADDATE, 'YYYY-MM-DD HH24:MI:SS') AS didDownLoadDate FROM TB_BRODSCHEDULE A JOIN TB_BRODCENTERSCH B ON A.BROD_CODE = B.BROD_CODE JOIN TB_CENTERINFO C ON B.CENTER_ID = C.CENTER_ID WHERE 1=1
AND C.CENTER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.BROD_NAME LIKE CONCAT('%', #{searchKeyword}, '%')
AND B.CREATE_CHECK = #{createCheck}
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT
    COALESCE(COUNT(*), 0)
FROM TB_BRODCENTERSCH
WHERE BROD_CODE = #{brodCode}
  AND CENTER_ID = #{centerId}

SELECT
    COALESCE(COUNT(*), 0)
FROM TB_BRODCENTERSCH
WHERE BROD_CODE = #{brodCode}
  AND CENTER_ID = #{centerId}
  AND CREATE_CHECK = #{createCheck}

mapper.update:
UPDATE TB_CENTERINFO SET
    BROD_CODE = #{brodCode}
WHERE CENTER_ID = #{centerId}

UPDATE TB_BRODCENTERSCH SET
                            DID_DOWNCHECK = #{didDownCheck},
                            DID_DOWNLOADDATE = NOW()
WHERE CENTER_ID = #{centerId}
  AND BROD_CODE = #{brodCode}

mapper.delete:
DELETE FROM TB_BRODCENTERSCH
WHERE BROD_CODE = #{brodCode}
  AND CENTER_ID = #{centerId}

DELETE FROM TB_BRODCENTERSCH
WHERE BROD_CODE != #{brodCode}
  AND CENTER_ID = #{centerId}


DELETE FROM TB_BRODCENTERSCH
WHERE BROD_CODE = #{brodCode}
  AND CREATE_CHECK = #{createCheck}
  AND CENTER_ID = #{centerId}
  AND SCHEDULE_SEQ <
      (
          SELECT MAX(SCHEDULE_SEQ)
          FROM TB_BRODCENTERSCH
          WHERE BROD_CODE = #{brodCode}
            AND CREATE_CHECK = #{createCheck}
            AND CENTER_ID = #{centerId}
      )
